import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "context-note",
  name: "Context Note",
  version: "1.0.0",
  async onLoad(ctx) {
    // 注册 context：id=task-note，contentFn 返回材料编号
