      kind: "context",
      context: {
        id: "task-note",
        contentFn: () => "CTX-7319",
      },
    });

    // 注册工具：context_ready，返回 ready=true
    ctx.register({
      kind: "tool",
      tool: {
        name: "context_ready",
        version: "1.0.0",
        description: "返回 ready=true，表示 task-note 上下文材料已就绪",
        permissions: { capabilities: [] },
        sideEffect: "none",
        parameters: {
          type: "object",
          properties: {},
